/// Atom-type equivalence levels (MMFF.I Table III, `MMFFDEF.PAR`).
///
/// `eq_level[0]` is the type itself (level 2 in Halgren's numbering);
/// `eq_level[1..3]` are the successively more general "default types" used
/// to resolve angle and torsion parameters that are not tabulated for the
/// full type quadruple.
#[derive(Debug, Clone, Copy)]
pub struct Mmff94Def {
    /// The four equivalence levels of this atom type, from the most specific
    /// (level 0, the type itself) to the most general. Level 0 is always the
    /// type's own number.
    pub eq_level: [u8; 4],
}

