/// Atom-type properties (MMFF.II Table I, `MMFFPROP.PAR`).
///
/// * `atno`  - atomic number
/// * `crd`  - number of connections (coordination number)
/// * `val`  - number of valence electrons
/// * `pilp` - 1 if the atom has a p-typed lone pair
/// * `mltb` - number of lone pairs on the atom
/// * `arom` - 1 if the atom is aromatic
/// * `linh` - 1 if the atom is linear (sp hybridised with 2 connections)
/// * `sbmb` - 1 if single bonds to this atom are "special" (conjugated)
#[derive(Debug, Clone, Copy)]
pub struct Mmff94Prop {
    /// Atomic number of the element.
    pub atno: u8,
    /// Number of connections (neighbours) of the atom.
    pub crd: u8,
    /// Total valence (bond-order sum) of the atom.
    pub val: u8,
    /// Number of π lone pairs on the atom.
    pub pilp: u8,
    /// Number of lone pairs on the atom.
    pub mltb: u8,
    /// `1` if the atom is aromatic, `0` otherwise.
    pub arom: u8,
    /// `1` if the atom is linear (sp hybridised with two connections).
    pub linh: u8,
    /// `1` if single bonds to this atom are "special" (conjugated).
    pub sbmb: u8,
}

