/// Global van der Waals parameters (MMFF.V Table I, `MMFFVDW.PAR`).
#[derive(Debug, Clone, Copy)]
pub struct Mmff94VdWGlobals {
    /// Exponent of `alpha_i` in `R*_i = A_i * alpha_i^power`.
    pub power: f64,
    /// Buffering coefficient `B` of the pair minimum rule.
    pub b: f64,
    /// Exponential damping coefficient `Beta`.
    pub beta: f64,
    /// Radius scaling applied to donor/acceptor pairs.
    pub darad: f64,
    /// Well depth scaling applied to donor/acceptor pairs.
    pub daeps: f64,
}

/// Global van der Waals combination-rule constants (MMFF.V, Table II).
pub const MMFF94_VDW_GLOBALS: Mmff94VdWGlobals = Mmff94VdWGlobals {
    power: 0.25,
    b: 0.2,
    beta: 12.0,
    darad: 0.8,
    daeps: 0.5,
};

/// Per-atom-type van der Waals parameters (`MMFFVDW.PAR`).
///
/// `da` encodes the MMFF donor/acceptor flag: 0 = none, 1 = acceptor,
/// 2 = donor.
#[derive(Debug, Clone, Copy)]
pub struct Mmff94VdWParam {
    /// MMFF94 atom type this row describes.
    pub atom_type: u8,
    /// Polarizability `alpha_i` in Å³.
    pub alpha_i: f64,
    /// Exponent `N_i` of the vdW combination rule (dimensionless).
    pub n_i: f64,
    /// Scaling coefficient `A_i` in Å⁴.
    pub a_i: f64,
    /// Well depth `G_i` in kcal·Å⁴/mol.
    pub g_i: f64,
    /// Donor/acceptor flag: `0` = none, `1` = acceptor, `2` = donor.
    pub da: u8,
}

